<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{$invoice->number??'Invoice draft'}}</title><style>@page{margin:37px 38px 45px}body{font-family:'DejaVu Sans',sans-serif;font-size:9px;color:#20392f;line-height:1.5}h1{font-size:28px;color:#153d34;margin:3px 0 8px}h2{font-size:11px;margin-top:22px}p{margin:5px 0;color:#617268}.eyebrow{font-size:9px;letter-spacing:1px;text-transform:uppercase;color:#a35b31}.header{width:100%;border-bottom:2px solid #153d34;margin-bottom:22px;padding-bottom:15px}.header td{vertical-align:top}.right{text-align:right}.muted{color:#617268}.items{width:100%;border-collapse:collapse;margin:18px 0 20px;table-layout:fixed}.items th{background:#153d34;color:white;text-align:left;font-size:8px;padding:9px 7px}.items td{padding:9px 7px;border-bottom:1px solid #dfe5dc;vertical-align:top;word-wrap:break-word}.items thead{display:table-header-group}.items tr{page-break-inside:avoid}.summary{width:55%;margin-left:45%;border-collapse:collapse}.summary td{border-bottom:1px solid #dfe5dc;padding:7px 5px}.grand{font-size:12px;font-weight:bold}.due{background:#e9eee2}.preline{white-space:pre-line}.draft{color:#a35b31;font-weight:bold}.footer{position:fixed;bottom:-25px;left:0;right:0;border-top:1px solid #dfe5dc;font-size:7px;color:#617268;padding-top:6px}.logo{max-width:110px;max-height:55px}</style></head><body>@php($company=$invoice->company_snapshot??$site)@php($customer=$invoice->customer_snapshot??$invoice->booking->only(['name','email','phone','country']))<table class="header"><tr><td>@if(!empty($company['logo_path']) && is_file(public_path($company['logo_path'])))<img class="logo" src="{{public_path($company['logo_path'])}}" alt="">@endif<div class="eyebrow">{{$company['company_name']??'Sparkling Tours and Safaris'}}</div><h1>INVOICE</h1><p class="preline">{{$company['address']??''}}<br>{{$company['email']??''}} {{$company['phone']??''}}</p></td><td class="right"><strong>{{$invoice->number??'DRAFT #'.$invoice->id}}</strong><p>Booking {{$invoice->booking->reference}}<br>Issued {{$invoice->issue_date?->format('d/m/Y')??'Not issued'}}<br>Due {{$invoice->due_date->format('d/m/Y')}}<br>Currency {{$invoice->currency}}</p><span class="{{$invoice->status==='draft'?'draft':''}}">{{strtoupper($invoice->status)}} / {{strtoupper($invoice->settlement())}}</span></td></tr></table><strong>BILL TO</strong><p>{{$customer['name']}}<br>{{$customer['email']}}<br>{{$customer['phone']??''}} · {{$customer['country']}}</p><table class="items"><thead><tr><th style="width:43%">Description</th><th style="width:20%">Qty / unit</th><th style="width:17%">Unit price</th><th style="width:20%">Amount</th></tr></thead><tbody>@foreach($invoice->items as $line)<tr><td>{{$line->description}}</td><td>{{$line->quantity}} / {{str_replace('_',' ',$line->unit)}}</td><td>{{$line->unit_price===null?'Pending':\App\Support\Money::format($line->unit_price,$invoice->currency)}}</td><td>{{$line->amount===null?'Pending':\App\Support\Money::format($line->amount,$invoice->currency)}}</td></tr>@endforeach</tbody></table><table class="summary">@foreach(['Subtotal'=>$invoice->subtotal,'Discount'=>$invoice->discount,'Tax'=>$invoice->tax_amount,'Grand total'=>$invoice->grand_total,'Deposit required'=>$invoice->deposit_required] as $label=>$amount)<tr><td>{{$label}}</td><td class="right">{{\App\Support\Money::format($amount,$invoice->currency)}}</td></tr>@endforeach<tr><td>Verified net paid</td><td class="right">{{\App\Support\Money::format($invoice->netPaidMinor(),$invoice->currency)}}</td></tr><tr><td>Outstanding balance</td><td class="right">{{\App\Support\Money::format($invoice->balanceMinor(),$invoice->currency)}}</td></tr><tr class="grand due"><td>Due now</td><td class="right">{{\App\Support\Money::format($invoice->dueNowMinor(),$invoice->currency)}}</td></tr></table><h2>PAYMENT INSTRUCTIONS</h2><p class="preline">{{$company['payment_instructions']??'Payment instructions not configured.'}}</p><p>Reference: {{$invoice->number??'Draft - do not pay'}}. {{$invoice->payment_mode==='deposit'?'Deposit requested; the balance remains payable under the agreed terms.':'Full payment requested.'}}</p><h2>AGREED TERMS</h2><p class="preline">{{$invoice->terms}}</p>@if($invoice->payments->isNotEmpty())<h2>VERIFIED PAYMENT ACKNOWLEDGEMENTS</h2><table class="items"><thead><tr><th>Date</th><th>Entry</th><th>Reference</th><th>Amount</th></tr></thead><tbody>@foreach($invoice->payments as $payment)<tr><td>{{$payment->paid_on->format('d/m/Y')}}</td><td>{{$payment->kind}}</td><td>{{$payment->transaction_reference}}</td><td>{{\App\Support\Money::format($payment->amount,$payment->currency)}}</td></tr>@endforeach</tbody></table>@endif<div class="footer">{{$company['company_name']??'Sparkling Tours'}} · {{$invoice->number??'DRAFT'}} · Reservation confirmation follows the agreed supplier and payment terms.</div></body></html>
